data link;
set t.crsp_with_gvkey;
keep gvkey lpermno datadate;
run;

data link;
set link;
if gvkey ^= "";
rename lpermno = permno;
rename datadate = date;
run;

proc sort data=link nodupkey; by permno date; run;

data codes;
set t.ncusip_link;
run;

proc sort data=crsp; by permno date; run;
proc sort data=codes; by permno date; run;

* Focus on common stocks (share codes 10 and 11);
data crsp;
merge crsp codes;
by permno date; 
if shrcd = 10 or shrcd = 11;
run;

* Cleanup;
proc datasets library = work noprint; delete codes index; run; quit;

data index;
set crsp.msi;
keep date ewretd;
if year(date) >= 1969;
run;

* Use CRSP monthly stocks from 1969 onwards, replacing returns with error codes by a missing value;
data crsp;
set crsp.msf;
keep permno date ret vol shrout;
if year(date) >= 1969;
if ret <= -1 then ret = .;
run;

data crsp;
merge crsp outliers;
by date;

if ret < r_1 and ret ^= . then ret = r_1;
if ret > r_99 and ret ^= . then ret = r_99;

trvol = vol/(10*shrout);

run;

proc datasets library=work noprint; delete outliers; run; quit;

proc sort data=crsp; by date; run;
proc sort data=index; by date; run;

data crsp;
merge crsp index; 
by date; 
aret = ret - ewretd;
run;

proc sort data=crsp; by permno date; run;
proc sort data=codes; by permno date; run;

* Focus on common stocks (share codes 10 and 11);
data crsp;
merge crsp codes;
by permno date; 
if shrcd = 10 or shrcd = 11;
run;

* Cleanup;
proc datasets library = work noprint; delete codes index; run; quit;

%macro rollstats;

%do y = 1970 %to 2020;

	%do m = 1 %to 12;

		data crsp_sub;
		set crsp;
		if 1 <= intck("MONTH",date,mdy(&m,15,&y)) <= 12;
		run;

		proc sort data=crsp_sub; by permno; run;

		proc univariate data = crsp_sub noprint;
		by permno;
		var ret;
		output out = retstat std = return_std_dev1 skewness = return_skewness1;
		run;
		quit;

		proc univariate data = crsp_sub noprint;
		by permno;
		var ret;
		output out = arstat mean=return1;
		run;
		quit;

		proc univariate data = crsp_sub noprint;
		by permno;
		var trvol;
		output out = volstat mean=turnover1; 
		run;
		quit;

		proc sort data=arstat; by permno; run;
		proc sort data=retstat; by permno; run;
		proc sort data=volstat; by permno; run;

		data retstat;
		merge arstat retstat volstat;
		by permno;
		year = &y;
		month = &m;
		run;

		proc sql;

			create table retstat as
				select r.*, l.gvkey 
				from retstat as r
				left join link as l
				on r.permno = l.permno
				and r.year = year(l.date)
				and r.month = month(l.date);

		quit;

		%if &y = 1970 and &m = 1 %then %do;
			data t.kimskinner(label = "Kim and Skinner (2012) variables");
			set retstat;
			label 	return1 = "Moving-average market-adjusted return (12-month window)"
					return_std_dev1 = "Moving-stdev of returns (12-month window)"
					return_skewness1 = "Moving-skewness of returns (12-month window)"
					turnover1 = "Moving average share turnover (% of outstanding shares, 12-month window)";
			run;
		%end;
		%else %do;
			proc append base=t.kimskinner data=retstat; run;
		%end;

* Load daily CRSP data;
data crsp;
set crsp.dsf;
if year(date) >= 1969;
keep permno date prc ret askhi bidlo vol shrout;
if prc < 0 then prc = -prc;
if ret < -1 then ret = .;
run;

proc sort data = crsp; by permno date; run;

data crsp;
set crsp;
by permno date; 
lprc = lag(prc);
if first.permno then lprc = .;
run;

data crsp; set crsp; dprc = prc - lprc; run;

* Compute relevant ratios (daily frequency);
data crsp;
set crsp;
year = year(date);
bidask = (askhi - bidlo)/prc;
amihud = abs(dprc)/(vol*prc/1000000);
run;

* Merge in daily Fama-French factors;
proc sql;

	create table crsp as
		select crsp.*, ff.rf, ff.mktrf, ff.smb, ff.hml
		from crsp
		left join ff.factors_daily as ff
		on crsp.date = ff.date;

quit;

data crsp;
set crsp;
exret = ret - rf;
run;

* Sort data and run regressions to estimate idiosyn;
proc sort data = crsp; by permno year; run;

proc reg data = crsp tableout rsquare outest = betas noprint;
by permno year;
model exret = mktrf smb hml;
run;
quit;

data betas_clean; set betas_clean; keep permno year _rsq_; run;
data betas_clean; set betas_clean; idiosyn = 1 - _rsq_; run;

proc sql;

	create table transparency as
		select permno, year, mean(bidask) as bidask, mean(amihud) as amihud
		from crsp
		group by permno, year;

	create table transparency as
		select t.*, b.idiosyn
		from transparency as t
		left join betas_clean as b
		on t.permno = b.permno
		and t.year = b.year;

quit;

data link;
set t.crsp_with_gvkey;
keep gvkey lpermno datadate;
run;

data link;
set link;
if gvkey ^= "";
rename lpermno = permno;
year = year(datadate);
run;

data link; set link; keep permno gvkey year; run;

proc sort data = link nodupkey; by permno year; run;
proc sort data = transparency; by permno year;

data transparency; 
merge transparency link;
by permno year; 
label 	bidask = "Yearly avg of daily bid-ask spead/prc"
		amihud = "Yearly avg of daily Amihud ratio"
		idiosyn = "1 - R2 from 3-factor model, yearly";
run;
